create table if not exists public.creator_protocol_constitutional_assets (id uuid primary key default gen_random_uuid(), constitution_id uuid not null, asset_kind text not null, display_name text not null, legal_owner_id uuid, custodian_id uuid, operator_id uuid, classification text not null default 'restricted', status text not null, evidence_manifest_id uuid, policy_version text not null, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_operators (id uuid primary key default gen_random_uuid(), constitution_id uuid not null, organization_id uuid not null, operator_class text not null, status text not null default 'candidate', accreditation_expires_at timestamptz, exit_package_manifest_id uuid, policy_version text not null, created_at timestamptz not null default now());
create table if not exists public.creator_protocol_forks (id uuid primary key default gen_random_uuid(), parent_protocol_version text not null, fork_protocol_version text not null, lineage_manifest_id uuid not null, namespace_status text not null, status text not null default 'proposed', created_at timestamptz not null default now());
create table if not exists public.creator_protocol_succession_cases (id uuid primary key default gen_random_uuid(), constitution_id uuid not null, trigger text not null, predecessor_id uuid, successor_candidate_id uuid, status text not null default 'opened', continuity_manifest_id uuid, policy_version text not null, created_at timestamptz not null default now());
alter table public.creator_protocol_constitutional_assets enable row level security; alter table public.creator_protocol_operators enable row level security; alter table public.creator_protocol_forks enable row level security; alter table public.creator_protocol_succession_cases enable row level security;
